<?php
namespace Modules\Finance\Http\Controllers;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Modules\Core\Support\CurrentCompany;use Modules\Finance\Models\PeriodCloseRun;use Modules\Finance\Services\PeriodCloseService;use RuntimeException;class PeriodCloseController extends Controller{public function __construct(private PeriodCloseService$service){}public function prepare(Request$request):JsonResponse{$d=$request->validate(['period'=>['required','regex:/^\d{4}-(0[1-9]|1[0-2])$/'],'backup_verified'=>'required|boolean','tax_reviewed'=>'required|boolean','notes'=>'nullable|string|max:2000']);return$this->domain(fn()=>response()->json($this->service->prepare(CurrentCompany::id(),$d['period'],$d,$request->user())));}public function approve(Request$request,PeriodCloseRun$periodCloseRun):JsonResponse{return$this->domain(fn()=>response()->json($this->service->approve($periodCloseRun,$request->user())));}public function close(Request$request,PeriodCloseRun$periodCloseRun):JsonResponse{return$this->domain(fn()=>response()->json($this->service->close($periodCloseRun,$request->user())));}private function domain(callable$c):JsonResponse{try{return$c();}catch(RuntimeException$e){return response()->json(['message'=>$e->getMessage()],422);}}}
